 public static class ProfileSecurity {
  public static string Protect(string text){return Convert.ToBase64String(ProtectedData.Protect(Encoding.UTF8.GetBytes(text??""),null,DataProtectionScope.CurrentUser));}
  public static string Reveal(string text){try{return Encoding.UTF8.GetString(ProtectedData.Unprotect(Convert.FromBase64String(text??""),null,DataProtectionScope.CurrentUser));}catch{throw new InvalidOperationException(I18n.T("Credencial indisponível. Informe-a novamente neste usuário do Windows."));}}
  public static string NormalizeUrl(string input){Uri uri;if(!Uri.TryCreate((input??"").Trim(),UriKind.Absolute,out uri)||(uri.Scheme!="http"&&uri.Scheme!="https")||uri.UserInfo.Length>0||uri.Query.Length>0||uri.Fragment.Length>0)throw new ArgumentException(I18n.T("URL HTTP/HTTPS inválida: não informe credenciais ou parâmetros."));string result=uri.GetLeftPart(UriPartial.Path).TrimEnd('/');foreach(string suffix in new[]{"/api/dispositivos-remotos","/api"})if(result.EndsWith(suffix,StringComparison.OrdinalIgnoreCase)){result=result.Substring(0,result.Length-suffix.Length);break;}if(Encoding.UTF8.GetByteCount(result)>256)throw new ArgumentException(I18n.T("URL muito longa."));return result;}
  public static string Fingerprint(string text){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(text))).Replace("-","").ToLowerInvariant();}
 }
 // Native tab controls paint unused header space and the page frame with
 // Windows system colors, even with OwnerDrawFixed. Paint that chrome last.
 public sealed class ProfileTabs : TabControl {
  Color surface=Color.FromArgb(9,38,57),border=Color.FromArgb(40,90,120),accent=Color.FromArgb(0,120,215);
  public void SetPalette(Color background,Color outline,Color selected){surface=background;border=outline;accent=selected;Invalidate();}
  protected override void OnResize(EventArgs e){base.OnResize(e);Invalidate();}
  protected override void OnSelectedIndexChanged(EventArgs e){base.OnSelectedIndexChanged(e);Invalidate();}
  protected override void WndProc(ref Message message){
   base.WndProc(ref message);
   if(IsDisposed||!IsHandleCreated)return;
   if(message.Msg==0x000F){using(var graphics=Graphics.FromHwnd(Handle))PaintChrome(graphics);}
   else if(message.Msg==0x0318&&message.WParam!=IntPtr.Zero){using(var graphics=Graphics.FromHdc(message.WParam))PaintChrome(graphics);}
  }
  void PaintChrome(Graphics graphics){
   if(ClientSize.Width<2||ClientSize.Height<2)return;
   Rectangle page=DisplayRectangle;
   using(var brush=new SolidBrush(surface)){
    graphics.FillRectangle(brush,0,0,ClientSize.Width,Math.Max(0,page.Top));
    graphics.FillRectangle(brush,0,page.Top,Math.Max(0,page.Left),Math.Max(0,ClientSize.Height-page.Top));
    graphics.FillRectangle(brush,page.Right,page.Top,Math.Max(0,ClientSize.Width-page.Right),Math.Max(0,ClientSize.Height-page.Top));
    graphics.FillRectangle(brush,0,page.Bottom,ClientSize.Width,Math.Max(0,ClientSize.Height-page.Bottom));
   }
   using(var pen=new Pen(border)){
    int top=Math.Max(0,page.Top-1);
    graphics.DrawRectangle(pen,0,top,ClientSize.Width-1,Math.Max(0,ClientSize.Height-top-1));
    for(int index=0;index<TabCount;index++){
     Rectangle tab=GetTabRect(index);bool selected=index==SelectedIndex;
     using(var brush=new SolidBrush(selected?accent:surface))graphics.FillRectangle(brush,tab);
     graphics.DrawRectangle(pen,tab.X,tab.Y,Math.Max(0,tab.Width-1),Math.Max(0,tab.Height-1));
     TextRenderer.DrawText(graphics,TabPages[index].Text,Font,tab,Color.White,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);
     if(selected&&Focused){var focus=tab;focus.Inflate(-4,-4);ControlPaint.DrawFocusRectangle(graphics,focus,Color.White,accent);}
    }
   }
  }
 }
 public sealed class ProfileGroupBox : GroupBox {
  public Color FrameColor {get;set;}
  public ProfileGroupBox(){FrameColor=Color.FromArgb(40,90,120);SetStyle(ControlStyles.UserPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.ResizeRedraw,true);}
  protected override void OnPaint(PaintEventArgs e){
   e.Graphics.Clear(BackColor);
   int top=Font.Height/2;
   using(var pen=new Pen(FrameColor))e.Graphics.DrawRectangle(pen,0,top,Math.Max(0,Width-1),Math.Max(0,Height-top-1));
   var caption=new Rectangle(7,0,Math.Min(Math.Max(0,Width-14),TextRenderer.MeasureText(Text,Font).Width+6),Font.Height+3);
   using(var brush=new SolidBrush(BackColor))e.Graphics.FillRectangle(brush,caption);
   TextRenderer.DrawText(e.Graphics,Text,Font,caption,ForeColor,TextFormatFlags.Left|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);
  }
 }
 // Preserve native input/accessibility while making disabled captions readable.
 public sealed class ProfileCheckBox : CheckBox {
  public Color OutlineColor {get;set;}
  public ProfileCheckBox(){OutlineColor=Color.FromArgb(40,90,120);SetStyle(ControlStyles.UserPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.ResizeRedraw,true);ForeColor=Color.FromArgb(225,237,244);}
  public override Size GetPreferredSize(Size proposedSize){var size=base.GetPreferredSize(proposedSize);return new Size(size.Width+6,Math.Max(size.Height,Font.Height+4));}
  protected override void OnPaint(PaintEventArgs e){
   e.Graphics.Clear(BackColor);
   int side=Math.Max(13,Font.Height);Size glyph=new Size(side,side);
   int x=RightToLeft==RightToLeft.Yes?Width-Padding.Right-glyph.Width:Padding.Left;
   int top=(Height-glyph.Height)/2;
   var box=new Rectangle(x,top,glyph.Width-1,glyph.Height-1);
   using(var brush=new SolidBrush(Checked?Color.FromArgb(18,78,106):Color.FromArgb(13,48,68)))e.Graphics.FillRectangle(brush,box);
   using(var pen=new Pen(OutlineColor))e.Graphics.DrawRectangle(pen,box);
   if(Checked)using(var pen=new Pen(Enabled?Color.White:Color.FromArgb(166,191,207),2))e.Graphics.DrawLines(pen,new[]{new Point(x+3,top+side/2),new Point(x+side/2-1,top+side-4),new Point(x+side-3,top+3)});
   var bounds=new Rectangle(Padding.Left+glyph.Width+6,Padding.Top,Math.Max(0,Width-Padding.Horizontal-glyph.Width-6),Math.Max(0,Height-Padding.Vertical));
   var flags=TextFormatFlags.Left|TextFormatFlags.VerticalCenter|TextFormatFlags.WordBreak;
   if(RightToLeft==RightToLeft.Yes){bounds.X=Padding.Left;flags=TextFormatFlags.Right|TextFormatFlags.RightToLeft|TextFormatFlags.VerticalCenter|TextFormatFlags.WordBreak;}
   if(!ShowKeyboardCues)flags|=TextFormatFlags.HidePrefix;
   TextRenderer.DrawText(e.Graphics,Text,Font,bounds,Enabled?ForeColor:Color.FromArgb(166,191,207),flags);
   if(Focused&&ShowFocusCues)ControlPaint.DrawFocusRectangle(e.Graphics,bounds,ForeColor,BackColor);
  }
 }
