 public sealed class ProfileButton : Button {
  protected override void OnPaint(PaintEventArgs e){
   if(Enabled){base.OnPaint(e);return;}
   Color background=Color.FromArgb(27,56,75),foreground=Color.FromArgb(166,191,207);
   e.Graphics.Clear(background);
   using(var pen=new Pen(Color.FromArgb(75,108,129)))e.Graphics.DrawRectangle(pen,0,0,Math.Max(0,Width-1),Math.Max(0,Height-1));
   var bounds=Rectangle.Inflate(ClientRectangle,-6,-2);
   if(Image!=null){int x=bounds.Left;int y=(Height-Image.Height)/2;ControlPaint.DrawImageDisabled(e.Graphics,Image,x,y,background);bounds.X+=Image.Width+5;bounds.Width=Math.Max(0,bounds.Width-Image.Width-5);}
   TextRenderer.DrawText(e.Graphics,Text,Font,bounds,foreground,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);
  }
 }
