  public static bool ValidServerFields(string[] fields,string existingKey){
   if(fields==null||fields.Length!=3||string.IsNullOrWhiteSpace(fields[0]))return false;
   try{ProfileSecurity.NormalizeUrl(fields[1]);}catch(ArgumentException){return false;}
   string key=string.IsNullOrEmpty(fields[2])?existingKey:fields[2];
   return !string.IsNullOrWhiteSpace(key)&&Encoding.UTF8.GetByteCount(key)>=32&&Encoding.UTF8.GetByteCount(key)<=256&&!key.Any(char.IsControl);
  }
  string ChooseCompany(string current){if(!settings.Companies.Any(c=>c.Active)){MessageBox.Show(L("Cadastre uma empresa primeiro.","Add a company first.","Registre una empresa primero."));return null;}using(var dialog=new Form{Text=L("Selecione a empresa","Select company","Seleccione la empresa"),Width=620,Height=165,StartPosition=FormStartPosition.CenterParent,Icon=Icon}){var box=new ProfileComboBox{Left=20,Top=20,Width=560,DropDownStyle=ComboBoxStyle.DropDownList};box.Items.AddRange(settings.Companies.Where(c=>c.Active).Cast<object>().ToArray());box.SelectedItem=settings.Companies.FirstOrDefault(c=>c.Id==current);if(box.SelectedIndex<0)box.SelectedIndex=0;var ok=new ProfileButton{Text=L("Continuar","Continue","Continuar"),Left=460,Top=65,Width=120,DialogResult=DialogResult.OK};dialog.Controls.Add(box);dialog.Controls.Add(ok);dialog.AcceptButton=ok;return dialog.ShowDialog(this)==DialogResult.OK?((CompanyProfile)box.SelectedItem).Id:null;}}
  void EditCompany(string id){var c=settings.Companies.FirstOrDefault(item=>item.Id==id);var f=ProfileDialog(L("Empresa","Company","Empresa"),new[]{L("ID no sistema","System ID","ID del sistema"),L("Nome","Name","Nombre"),L("Endereço","Address","Dirección"),L("Cidade","City","Ciudad"),L("Estado","State","Estado"),L("País","Country","País")},c==null?new string[6]:new[]{c.Id,c.Name,c.Address,c.City,c.State,c.Country},-1,c!=null,c==null?true:c.Active,new[]{"Ativa para novas compilações","Active for new builds","Activa para nuevas compilaciones"});if(f==null)return;if(!Regex.IsMatch(f[0],"^[A-Za-z0-9-]{1,64}$")||string.IsNullOrWhiteSpace(f[1])||(c==null&&settings.Companies.Any(item=>item.Id==f[0]))){MessageBox.Show(L("Informe nome e ID único válido, com até 64 letras, números ou hífen.","Enter a name and unique ID, up to 64 letters, digits or hyphens.","Indique nombre e ID único, hasta 64 letras, números o guiones."));return;}if(c==null){c=new CompanyProfile();settings.Companies.Add(c);}c.Id=f[0];c.Name=f[1].Trim();c.Address=f[2];c.City=f[3];c.State=f[4];c.Country=f[5];c.Active=Convert.ToBoolean(f[6]);SaveSettings();RefreshProfileData();}
  void EditServer(string id){
   var server=settings.Servers.FirstOrDefault(item=>item.Id==id);string company=ChooseCompany(server==null?null:server.CompanyId);if(company==null)return;
   var selectedCompany=settings.Companies.First(item=>item.Id==company);
   string existingKey=server==null?null:ProfileSecurity.Reveal(server.ProtectedKey);
   Func<string[],bool> validate=delegate(string[] candidate){if(!ValidServerFields(candidate,existingKey))return false;string url=ProfileSecurity.NormalizeUrl(candidate[1]);return !settings.Servers.Any(item=>item.Id!=id&&item.CompanyId==company&&item.BaseUrl==url);};
   string title=server==null?L("Cadastrar servidor / URL","Add server / URL","Registrar servidor / URL"):L("Editar servidor / URL","Edit server / URL","Editar servidor / URL");
   string keyLabel=server==null?L("Chave API (obrigatória)","API key (required)","Clave API (obligatoria)"):L("Chave API (em branco mantém a atual)","API key (blank keeps current)","Clave API (vacío conserva la actual)");
   var fields=ProfileDialog(title,new[]{L("Nome / ambiente","Name / environment","Nombre / entorno"),"URL",keyLabel},server==null?new string[3]:new[]{server.Name,server.BaseUrl,""},2,false,null,null,L("Empresa: ","Company: ","Empresa: ")+selectedCompany.Name+" — "+company,validate);
   if(fields==null)return;
   try{
    if(!validate(fields))throw new ArgumentException(L("Confira nome, URL e chave API (32 a 256 bytes). A URL não pode estar repetida nesta empresa.","Check name, URL and API key (32 to 256 bytes). The URL must not be duplicated within this company.","Revise nombre, URL y clave API (32 a 256 bytes). La URL no puede repetirse en esta empresa."));
    string key=fields[2].Length>0?fields[2]:existingKey;
    if(server==null){server=new ServerProfile{Id=Guid.NewGuid().ToString()};settings.Servers.Add(server);}
    server.CompanyId=company;server.Name=fields[0].Trim();server.BaseUrl=ProfileSecurity.NormalizeUrl(fields[1]);server.ProtectedKey=ProfileSecurity.Protect(key);server.LastCheckedUtc=null;server.LastCheckPassed=false;SaveSettings();RefreshProfileData();
   }catch(Exception error){MessageBox.Show(error.Message);}
  }
  void EditWifi(string id){var w=settings.WifiNetworks.FirstOrDefault(item=>item.Id==id);string company=ChooseCompany(w==null?null:w.CompanyId);if(company==null)return;var f=ProfileDialog(L("Rede Wi-Fi","Wi-Fi network","Red Wi-Fi"),new[]{L("Nome","Name","Nombre"),"SSID",L("Senha (em branco mantém a atual)","Password (blank keeps current)","Contraseña (vacío conserva la actual)")},w==null?new string[3]:new[]{w.Name,w.Ssid,""},2,false,w!=null&&w.OpenNetwork,new[]{"Rede aberta (sem senha)","Open network (no password)","Red abierta (sin contraseña)"});if(f==null)return;try{string pass=f[2].Length>0?f[2]:w==null?"":ProfileSecurity.Reveal(w.ProtectedPassword);if(Convert.ToBoolean(f[3]))pass="";if(string.IsNullOrWhiteSpace(f[0])||Encoding.UTF8.GetByteCount(f[1])<1||Encoding.UTF8.GetByteCount(f[1])>32||(!Convert.ToBoolean(f[3])&&(Encoding.UTF8.GetByteCount(pass)<8||Encoding.UTF8.GetByteCount(pass)>63)))throw new ArgumentException(L("Confira nome, SSID (1 a 32 bytes) e senha (8 a 63 bytes ou rede aberta).","Check name, SSID (1 to 32 bytes) and password (8 to 63 bytes or open network).","Revise nombre, SSID (1 a 32 bytes) y contraseña (8 a 63 bytes o red abierta)."));if(w==null){w=new WifiProfile{Id=Guid.NewGuid().ToString()};settings.WifiNetworks.Add(w);}w.CompanyId=company;w.Name=f[0].Trim();w.Ssid=f[1];w.ProtectedPassword=ProfileSecurity.Protect(pass);w.OpenNetwork=Convert.ToBoolean(f[3]);SaveSettings();RefreshProfileData();}catch(Exception error){MessageBox.Show(error.Message);}}
  bool ConfirmProfileRemoval(){return MessageBox.Show(L("Remover este cadastro local do Studio? Não altera o sistema nem os ESPs.","Remove this local Studio entry? System and ESP data stay unchanged.","¿Eliminar este registro local de Studio? No modifica el sistema ni los ESP."),Text,MessageBoxButtons.YesNo)==DialogResult.Yes;}
  void RemoveCompany(string id){if(settings.Servers.Any(s=>s.CompanyId==id)||settings.WifiNetworks.Any(w=>w.CompanyId==id)){MessageBox.Show(L("Remova primeiro os servidores e redes desta empresa.","Remove this company's servers and networks first.","Elimine primero los servidores y redes de esta empresa."));return;}if(ConfirmProfileRemoval()){settings.Companies.RemoveAll(c=>c.Id==id);SaveSettings();RefreshProfileData();}}
  void RemoveServer(string id){if(ConfirmProfileRemoval()){settings.Servers.RemoveAll(s=>s.Id==id);SaveSettings();RefreshProfileData();}}
  void RemoveWifi(string id){if(ConfirmProfileRemoval()){settings.WifiNetworks.RemoveAll(w=>w.Id==id);SaveSettings();RefreshProfileData();}}
  void RefreshProfileData(){if(companyGrid==null)return;settings.Companies=settings.Companies??new List<CompanyProfile>();settings.Servers=settings.Servers??new List<ServerProfile>();settings.WifiNetworks=settings.WifiNetworks??new List<WifiProfile>();companyGrid.DataSource=settings.Companies.Select(c=>new{ID=c.Id,Company=c.Name,Address=c.Address,City=c.City,State=c.State,Country=c.Country,Active=c.Active}).ToList();serverGrid.DataSource=settings.Servers.Select(s=>new{ID=s.Id,Company=s.CompanyId,Name=s.Name,URL=s.BaseUrl}).ToList();if(serverGrid.Columns.Count>0)serverGrid.Columns[0].Visible=false;wifiGrid.DataSource=settings.WifiNetworks.Select(w=>new{ID=w.Id,Company=w.CompanyId,Name=w.Name,SSID=w.Ssid}).ToList();if(wifiGrid.Columns.Count>0)wifiGrid.Columns[0].Visible=false;refreshingProfiles=true;var p=SelectedProject;companyProfileBox.Items.Clear();companyProfileBox.Items.AddRange(settings.Companies.Where(c=>c.Active).Cast<object>().ToArray());companyProfileBox.SelectedItem=p==null?null:settings.Companies.FirstOrDefault(c=>c.Id==p.CompanyId);wifiModeBox.SelectedIndex=p!=null&&p.WifiMode=="initial"?1:0;inheritProfileBox.Checked=p!=null&&p.InheritProfile;adoptProfileBox.Checked=p!=null&&p.AdoptLegacy;RefreshDependentProfiles(p==null?null:p.ServerId,p==null?null:p.WifiId);refreshingProfiles=false;SetProfileEnabled();LocalizeProfileGrids();ShowLastProfileCheck();}
  void RefreshDependentProfiles(string serverId,string wifiId){bool previous=refreshingProfiles;refreshingProfiles=true;var c=companyProfileBox.SelectedItem as CompanyProfile;serverProfileBox.Items.Clear();wifiProfileBox.Items.Clear();if(c!=null){serverProfileBox.Items.AddRange(settings.Servers.Where(s=>s.CompanyId==c.Id).Cast<object>().ToArray());wifiProfileBox.Items.AddRange(settings.WifiNetworks.Where(w=>w.CompanyId==c.Id).Cast<object>().ToArray());}serverProfileBox.SelectedItem=settings.Servers.FirstOrDefault(s=>s.Id==serverId&&c!=null&&s.CompanyId==c.Id);wifiProfileBox.SelectedItem=settings.WifiNetworks.FirstOrDefault(w=>w.Id==wifiId&&c!=null&&w.CompanyId==c.Id);refreshingProfiles=previous;}
  string ProfileKind(){string file=Path.Combine(folderBox.Text,"firmware-profile.json");if(!File.Exists(file))return null;var data=profileJson.Deserialize<Dictionary<string,object>>(File.ReadAllText(file));return Convert.ToString(data["kind"]);}
  void ShowLastProfileCheck(){if(testingProfile)return;var server=serverProfileBox.SelectedItem as ServerProfile;DateTime time;if(server==null||!DateTime.TryParse(server.LastCheckedUtc,out time))return;profileTestLabel.ForeColor=server.LastCheckPassed?Color.FromArgb(103,226,172):Color.FromArgb(255,151,151);profileTestLabel.Text=L("Último teste: ","Last test: ","Última prueba: ")+(server.LastCheckPassed?L("confirmado — ","confirmed — ","confirmado — "):L("falhou — ","failed — ","falló — "))+time.ToLocalTime().ToString("dd/MM/yyyy HH:mm:ss");}
  void SetProfileEnabled(){string kind=null;try{kind=ProfileKind();}catch{}bool compatible=kind!=null;bool bootstrap=kind=="bootstrap";
   if(bootstrap){bool old=refreshingProfiles;refreshingProfiles=true;inheritProfileBox.Checked=false;wifiModeBox.SelectedIndex=1;refreshingProfiles=old;if(SelectedProject!=null){SelectedProject.InheritProfile=false;SelectedProject.WifiMode="initial";}}
   if(compatible&&!bootstrap){bool old=refreshingProfiles;refreshingProfiles=true;inheritProfileBox.Checked=true;wifiModeBox.SelectedIndex=0;refreshingProfiles=old;if(SelectedProject!=null){SelectedProject.InheritProfile=true;SelectedProject.WifiMode="system";}}
   inheritProfileBox.Visible=compatible&&!bootstrap;
   bool inherit=inheritProfileBox.Checked;companyProfileBox.Enabled=serverProfileBox.Enabled=wifiModeBox.Enabled=compatible&&!inherit;wifiModeBox.Enabled=compatible&&!inherit&&!bootstrap;wifiProfileBox.Enabled=compatible&&!inherit&&wifiModeBox.SelectedIndex==1;adoptProfileBox.Enabled=compatible&&!inherit;inheritProfileBox.Enabled=false;profileTestButton.Enabled=!testingProfile&&serverProfileBox.SelectedItem!=null&&!inherit;}
  void ProfileSelectionChanged(){if(refreshingProfiles)return;var p=SelectedProject;if(p!=null){p.CompanyId=(companyProfileBox.SelectedItem as CompanyProfile??new CompanyProfile()).Id;p.ServerId=(serverProfileBox.SelectedItem as ServerProfile??new ServerProfile()).Id;p.WifiId=(wifiProfileBox.SelectedItem as WifiProfile??new WifiProfile()).Id;p.WifiMode=wifiModeBox.SelectedIndex==1?"initial":"system";p.InheritProfile=inheritProfileBox.Checked;p.AdoptLegacy=adoptProfileBox.Checked;SaveSettings();}PText(profileTestLabel,"Teste pendente","Not tested","Prueba pendiente");profileTestLabel.ForeColor=Color.FromArgb(166,191,207);SetProfileEnabled();ShowLastProfileCheck();RefreshArtifacts();}
  string SelectedProfileJson(){string kind=ProfileKind();if(kind==null)return null;if(inheritProfileBox.Checked){if(kind=="bootstrap")throw new InvalidOperationException(L("Bootstrap exige empresa, servidor e rede inicial.","Bootstrap requires company, server and initial network.","Bootstrap requiere empresa, servidor y red inicial."));return profileJson.Serialize(new{schema=1,mode="inherit"});}var c=companyProfileBox.SelectedItem as CompanyProfile;var s=serverProfileBox.SelectedItem as ServerProfile;var w=wifiProfileBox.SelectedItem as WifiProfile;if(c==null||s==null||s.CompanyId!=c.Id)throw new InvalidOperationException(L("Selecione empresa e servidor correspondentes.","Select company and matching server.","Seleccione empresa y servidor correspondientes."));bool initial=wifiModeBox.SelectedIndex==1;if((kind=="bootstrap"&&!initial)||(initial&&(w==null||w.CompanyId!=c.Id)))throw new InvalidOperationException(L("Selecione uma rede inicial da empresa.","Select an initial network belonging to the company.","Seleccione una red inicial de la empresa."));return profileJson.Serialize(new{schema=1,mode="installation",empresaId=c.Id,baseUrl=ProfileSecurity.NormalizeUrl(s.BaseUrl),apiKey=ProfileSecurity.Reveal(s.ProtectedKey),wifiMode=initial?"initial":"system",ssid=initial?w.Ssid:"",password=initial?ProfileSecurity.Reveal(w.ProtectedPassword):"",adoptLegacy=adoptProfileBox.Checked});}
  bool ConfirmProfileBuild(){try{string json=SelectedProfileJson();if(json==null)return true;string company=inheritProfileBox.Checked?L("Configuração já instalada no ESP","Configuration already installed on the ESP","Configuración ya instalada en el ESP"):((CompanyProfile)companyProfileBox.SelectedItem).ToString();string server=inheritProfileBox.Checked?L("Preservado no ESP","Preserved on the ESP","Conservado en el ESP"):((ServerProfile)serverProfileBox.SelectedItem).BaseUrl;string wifi=wifiModeBox.SelectedIndex==1&&!inheritProfileBox.Checked?((WifiProfile)wifiProfileBox.SelectedItem).Ssid:L("Gerenciado pelo sistema","Managed by system","Administrado por el sistema");string text=L("Confira o destino antes de compilar:","Review the destination before building:","Revise el destino antes de compilar:")+"\n\n"+company+"\n"+server+"\nWi-Fi: "+wifi;if(adoptProfileBox.Checked&&!inheritProfileBox.Checked)text+="\n\n"+L("Adoção de instalação antiga autorizada neste destino. A fila de outra empresa será recusada.","Legacy installation adoption is authorized at this destination. Another company's queue will be refused.","Adopción de instalación antigua autorizada en este destino. Se rechazará la cola de otra empresa.");return MessageBox.Show(text,Text,MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes;}catch(Exception error){MessageBox.Show(error.Message);return false;}}
  string ProfileForNewBuild(string json) {
   var data=profileJson.Deserialize<Dictionary<string,object>>(json);
   if(data.ContainsKey("wifiMode")&&Convert.ToString(data["wifiMode"])=="initial")data["wifiApplyId"]=Guid.NewGuid().ToString("N");
   return profileJson.Serialize(data);
  }
  bool PrepareProfileBuild(){try{activeProfileJson=SelectedProfileJson();activeProfileBuild=activeProfileJson!=null;if(!activeProfileBuild)return true;activeProfileFingerprint=SelectedProfileFingerprint(activeProfileJson);activeProfileJson=ProfileForNewBuild(activeProfileJson);activeProfileCompany=inheritProfileBox.Checked?null:((CompanyProfile)companyProfileBox.SelectedItem).Id;activeProfileServer=inheritProfileBox.Checked?"":((ServerProfile)serverProfileBox.SelectedItem).BaseUrl;activeProfileBuildRoot=Path.Combine(settingsFolder,"Builds",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(activeProfileBuildRoot);activeProfileFile=Path.Combine(activeProfileBuildRoot,"profile.json");File.WriteAllText(activeProfileFile,activeProfileJson,new UTF8Encoding(false));SelectedProject.LastArtifactDirectory=null;SelectedProject.LastProfileFingerprint=null;SelectedProject.LastArtifactHash=null;SaveSettings();RefreshArtifacts();return true;}catch(Exception error){MessageBox.Show(error.Message);return false;}}
  void FinishProfileBuild(bool success){if(!activeProfileBuild)return;try{string output=Path.Combine(activeProfileBuildRoot,"build",environmentBox.Text),firmware=Path.Combine(output,"firmware.bin");if(success&&File.Exists(firmware)){string destination=Path.Combine(settingsFolder,"Artifacts",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(destination);foreach(string file in Directory.GetFiles(output))if(new[]{".bin",".elf",".map",".hex"}.Contains(Path.GetExtension(file).ToLowerInvariant()))File.Copy(file,Path.Combine(destination,Path.GetFileName(file)));string sha=CalculateSha256(Path.Combine(destination,"firmware.bin"));File.WriteAllText(Path.Combine(destination,"profile-manifest.json"),profileJson.Serialize(new{schema=1,mode=inheritProfileBox.Checked?"inherit":"installation",companyId=activeProfileCompany,server=activeProfileServer,kind=ProfileKind(),artifactProtocol=2,board="esp32dev",project=nameBox.Text,environment=environmentBox.Text,profileFingerprint=activeProfileFingerprint,sha256=sha,utc=DateTime.UtcNow.ToString("o")}),new UTF8Encoding(false));SelectedProject.LastArtifactDirectory=destination;SelectedProject.LastProfileFingerprint=activeProfileFingerprint;SelectedProject.LastArtifactHash=sha;}}finally{if(activeProfileFile!=null&&File.Exists(activeProfileFile))File.Delete(activeProfileFile);string header=Path.Combine(activeProfileBuildRoot,"build",environmentBox.Text,"private-profile","firmware_profile_generated.h");if(File.Exists(header))File.Delete(header);activeProfileJson=null;}}
  string SelectedProfileFingerprint(string json){return ProfileSecurity.Fingerprint(profileJson.Serialize(new{profile=json,folder=Path.GetFullPath(folderBox.Text),environment=environmentBox.Text,kind=ProfileKind()}));}
  string VerifiedProfileArtifacts(){try{var p=SelectedProject;if(p==null||string.IsNullOrEmpty(p.LastArtifactDirectory))return null;string json=SelectedProfileJson();if(json==null||SelectedProfileFingerprint(json)!=p.LastProfileFingerprint)return null;string firmware=Path.Combine(p.LastArtifactDirectory,"firmware.bin");return File.Exists(firmware)&&CalculateSha256(firmware)==p.LastArtifactHash?p.LastArtifactDirectory:null;}catch{return null;}}
  string RedactProfileLog(string text){if(text.Contains("FW_PROFILE_API_KEY")||text.Contains("FW_PROFILE_WIFI_PASSWORD"))return "[credencial omitida]"+Environment.NewLine;if(activeProfileJson!=null){var data=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(activeProfileJson);foreach(string field in new[]{"apiKey","password"})if(data.ContainsKey(field)&&Convert.ToString(data[field]).Length>0)text=text.Replace(Convert.ToString(data[field]),"[credencial omitida]");}return text;}
  async void TestProfileConnection(){var s=serverProfileBox.SelectedItem as ServerProfile;var c=companyProfileBox.SelectedItem as CompanyProfile;if(s==null||c==null||testingProfile)return;string testedConfiguration=s.BaseUrl+"|"+s.ProtectedKey;testingProfile=true;SetProfileEnabled();profileTestLabel.Text=L("Verificando servidor, chave e empresa...","Checking server, key and company...","Verificando servidor, clave y empresa...");try{string key=ProfileSecurity.Reveal(s.ProtectedKey),baseUrl=ProfileSecurity.NormalizeUrl(s.BaseUrl),companyId=c.Id;var result=await Task.Run(delegate{var request=(HttpWebRequest)WebRequest.Create(baseUrl+"/api/dispositivos-remotos/diagnostico?empresaId="+Uri.EscapeDataString(companyId));request.Method="GET";request.AllowAutoRedirect=false;request.Timeout=12000;request.ReadWriteTimeout=12000;request.Headers["x-api-key"]=key;using(var response=(HttpWebResponse)request.GetResponse()){if(response.StatusCode!=HttpStatusCode.OK)throw new InvalidOperationException("Resposta incompatível.");using(var reader=new StreamReader(response.GetResponseStream())){char[] buffer=new char[65537];int used=0,read;while(used<buffer.Length&&(read=reader.Read(buffer,used,buffer.Length-used))>0)used+=read;if(used>65536)throw new InvalidOperationException("Resposta muito grande.");return new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(new string(buffer,0,used));}}});if(!result.ContainsKey("protocol")||Convert.ToString(result["protocol"])!="firmware-profile-v1"||!result.ContainsKey("empresaId")||Convert.ToString(result["empresaId"])!=companyId||!result.ContainsKey("ready")||!Convert.ToBoolean(result["ready"]))throw new InvalidOperationException("Resposta incompatível.");if(serverProfileBox.SelectedItem==s&&companyProfileBox.SelectedItem==c&&testedConfiguration==s.BaseUrl+"|"+s.ProtectedKey){s.LastCheckedUtc=DateTime.UtcNow.ToString("o");s.LastCheckPassed=true;SaveSettings();profileTestLabel.ForeColor=Color.FromArgb(103,226,172);profileTestLabel.Text=L("✓ API, chave e empresa confirmadas neste computador — ","✓ API, key and company confirmed on this computer — ","✓ API, clave y empresa confirmadas en este equipo — ")+DateTime.Now.ToString("HH:mm:ss");}}catch(Exception error){if(serverProfileBox.SelectedItem==s&&companyProfileBox.SelectedItem==c&&testedConfiguration==s.BaseUrl+"|"+s.ProtectedKey){s.LastCheckedUtc=DateTime.UtcNow.ToString("o");s.LastCheckPassed=false;SaveSettings();profileTestLabel.ForeColor=Color.FromArgb(255,151,151);var web=error as WebException;var response=web==null?null:web.Response as HttpWebResponse;profileTestLabel.Text=L("Falha no teste: ","Connection test failed: ","Error de prueba: ")+(response==null?L("servidor indisponível, TLS ou API incompatível.","server unavailable, TLS or incompatible API.","servidor no disponible, TLS o API incompatible."):"HTTP "+(int)response.StatusCode);if(response!=null)response.Dispose();}}finally{testingProfile=false;if(!IsDisposed)SetProfileEnabled();}}
  bool ExportProtectedProfileScript(string extension){string json;try{json=SelectedProfileJson();}catch(Exception error){MessageBox.Show(error.Message);return true;}if(json==null)return false;using(var dialog=new SaveFileDialog{FileName="compilar-perfil"+extension,Filter="Script|*"+extension}){if(dialog.ShowDialog(this)!=DialogResult.OK)return true;File.WriteAllText(dialog.FileName,BuildProtectedProfileScript(json,extension),new UTF8Encoding(extension!=".bat"));return true;}}
  string BuildProtectedProfileScript(string json,string extension){string encrypted=ProfileSecurity.Protect(json);Func<string,string> quote=value=>"'"+value.Replace("'","''")+"'";string script="$ErrorActionPreference = 'Stop'\r\nAdd-Type -AssemblyName System.Security\r\n$buildFolder = Join-Path $env:LOCALAPPDATA ('FirmwareBuild-' + [guid]::NewGuid().ToString('N'))\r\nNew-Item -ItemType Directory -Path $buildFolder | Out-Null\r\n$profileFile = Join-Path $buildFolder 'profile.json'\r\n$oldProfile = $env:FIRMWARE_PROFILE_FILE\r\n$oldBuild = $env:PLATFORMIO_BUILD_DIR\r\ntry {\r\n$bytes = [Security.Cryptography.ProtectedData]::Unprotect([Convert]::FromBase64String('"+encrypted+"'), $null, [Security.Cryptography.DataProtectionScope]::CurrentUser)\r\n[IO.File]::WriteAllBytes($profileFile, $bytes)\r\n$profileData = [Text.Encoding]::UTF8.GetString($bytes) | ConvertFrom-Json\r\nif ($profileData.wifiMode -eq 'initial') {\r\n$profileData | Add-Member -NotePropertyName wifiApplyId -NotePropertyValue ([guid]::NewGuid().ToString('N')) -Force\r\n[IO.File]::WriteAllText($profileFile, ($profileData | ConvertTo-Json -Depth 8 -Compress), (New-Object Text.UTF8Encoding($false)))\r\n}\r\n$env:FIRMWARE_PROFILE_FILE = $profileFile\r\n$env:PLATFORMIO_BUILD_DIR = Join-Path $buildFolder 'build'\r\nSet-Location -LiteralPath "+quote(folderBox.Text)+"\r\n& "+quote(platformIoBox.Text)+" run -e "+quote(environmentBox.Text)+"\r\nif ($LASTEXITCODE -ne 0) { throw 'Falha na compilacao.' }\r\nWrite-Host ('Arquivos gerados em: ' + $env:PLATFORMIO_BUILD_DIR)\r\n} finally {\r\nRemove-Item -LiteralPath $profileFile -ErrorAction SilentlyContinue\r\nRemove-Item -LiteralPath (Join-Path $buildFolder "+quote("build/"+environmentBox.Text+"/private-profile/firmware_profile_generated.h")+") -ErrorAction SilentlyContinue\r\n$env:FIRMWARE_PROFILE_FILE = $oldProfile\r\n$env:PLATFORMIO_BUILD_DIR = $oldBuild\r\n}\r\n";if(extension==".bat")script="@echo off\r\npowershell.exe -NoProfile -EncodedCommand "+Convert.ToBase64String(Encoding.Unicode.GetBytes(script))+"\r\nexit /b %errorlevel%\r\n";return script;}
 }
